"""API source for ingesting records from REST APIs."""

import json
import logging
from typing import Any, Iterator

import requests

from .models import Record, BatchResult

logger = logging.getLogger(__name__)


def fetch_page(
    base_url: str,
    params: dict[str, Any] | None = None,
    headers: dict[str, str] | None = None,
    page: int = 1,
) -> Iterator[dict[str, Any]]:
    """Fetch a single page of results from an API."""
    url = f"{base_url}?page={page}"
    if params:
        for key, value in params.items():
            url += f"&{key}={value}"

    response = requests.get(url, headers=headers)
    response.raise_for_status()

    data = response.json()
    if isinstance(data, list):
        yield from data
    elif isinstance(data, dict) and "data" in data:
        yield from data["data"]


def fetch_all_pages(
    base_url: str,
    params: dict[str, Any] | None = None,
    headers: dict[str, str] | None = None,
    max_pages: int | None = None,
) -> Iterator[dict[str, Any]]:
    """Fetch all pages of results from an API."""
    page = 1
    while max_pages is None or page <= max_pages:
        for item in fetch_page(base_url, params, headers, page):
            yield item
        page += 1
        # Check if there are more pages
        try:
            response = requests.get(base_url, params=params, headers=headers)
            response.raise_for_status()
            data = response.json()
            if not isinstance(data, list) and "data" in data:
                meta = data.get("meta", {})
                total_pages = meta.get("total_pages", 1)
                if page >= total_pages:
                    break
        except Exception:
            break


def build_auth_headers(api_key: str | None = None) -> dict[str, str]:
    """Build authentication headers for API requests."""
    headers: dict[str, str] = {}
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
    return headers


def ingest_from_api(
    config: dict[str, Any],
    record_factory: Any | None = None,
) -> BatchResult:
    """Ingest records from an API endpoint."""
    result = BatchResult()
    base_url = config.get("base_url", "")
    api_key = config.get("api_key")
    headers = build_auth_headers(api_key)
    max_pages = config.get("max_pages")

    try:
        for item in fetch_all_pages(base_url, headers=headers, max_pages=max_pages):
            if record_factory:
                record = record_factory(item)
                if record:
                    result.add_success()
            else:
                result.add_success()
        logger.info(f"Ingested {result.success} records from API")
    except Exception as exc:
        result.add_failure(f"API ingestion failed: {exc}")
        logger.error(f"API ingestion failed: {exc}")

    return result
EOF

